fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>
) {
    let n = vals_1.len();

    // Assumptions: vals_2, conds_1, conds_2 must have the same length n
    // Each integer in vals_1 and vals_2 is < 1000
    // For each i, at least one of conds_1[i] or conds_2[i] is true

    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        let v1 = vals_1[i];
        let v2 = vals_2[i];

        if c1 && c2 {
            // Both true: average (integer division)
            avgs.push((v1 + v2) / 2);
        } else if c1 {
            // Only first true
            avgs.push(v1);
        } else {
            // Only second true
            avgs.push(v2);
        }
    }
}